#include "Monstey_GadbScalarFloat.hpp"
#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>
using namespace Monstey;
namespace {
using U64=std::uint64_t;using U32=std::uint32_t;
U64 checks=0,cases=0;U32 groups=0;
void Check(bool b){++checks;if(!b)throw std::runtime_error("Independent scalar assertion");}
struct Image{
 U64 base;std::vector<std::uint8_t> data;
 static constexpr U32 hash=0x5a1100cc;
 explicit Image(std::size_t n=0x10000,U64 address=0x100000):base(address),data(n){}
 U64 R()const{return base+0x100;}U64 K()const{return base+0x180;}U64 D()const{return base+0x1c0;}U64 H()const{return base+0x200;}U64 O()const{return base+0x280;}U64 C()const{return base+0x300;}U64 T()const{return base+0x400;}U64 V()const{return base+0x6000;}U64 A()const{return base+0x8000;}U64 Out()const{return base+0x40;}
 Monstey_GadbBinderMemory M(){return{base,data};}
 void Put(U64 p,U64 value,std::size_t n){if(p<base||p-base>data.size()||n>data.size()-static_cast<std::size_t>(p-base))throw std::runtime_error("Bad independent fixture store");for(std::size_t i=0;i<n;++i)data[static_cast<std::size_t>(p-base)+i]=static_cast<std::uint8_t>(value>>(i*8));}
 U64 Get(U64 p,std::size_t n)const{if(p<base||p-base>data.size()||n>data.size()-static_cast<std::size_t>(p-base))throw std::runtime_error("Bad independent fixture read");U64 v=0;for(std::size_t i=0;i<n;++i)v|=U64(data[static_cast<std::size_t>(p-base)+i])<<(i*8);return v;}
 void Decl(U32 i,U32 h,U32 type,U32 count,U32 flags=0){const auto p=T()+U64(i)*72;Put(p+32,h,4);Put(p+36,type,4);Put(p+40,count,4);Put(p+44,flags,4);}
 void Setup(){Put(R(),1,1);Put(R()+1,1,1);Put(R()+8,H(),8);Put(R()+16,V(),8);Put(R()+24,O(),8);Put(K(),hash,4);Put(D(),0xffc12345,4);Put(H(),hash,4);Put(H()+10,2,1);Put(H()+12,1,2);Put(H()+14,0,2);Put(O()+32,C(),8);Put(C(),T(),8);Put(C()+8,1,4);Decl(0,hash,2,1);}
};
U32 LiteralSize(U32 type,U32 count,U32 flags){constexpr std::array<U32,18> sizes{0,5,8,8,8,8,8,8,12,16,8,8,8,8,8,8,8,8};if(flags&0x280u)return 0;return count==1?(type<sizes.size()?sizes[type]:0u):16u;}
template<class F>void RangeFault(F f,U64 address){bool found=false;try{f();}catch(const Monstey_GadbBinderFault&e){found=e.kind==Monstey_GadbBinderFaultKind::ConsumedRangeUnavailable&&e.address==address;}Check(found);}
template<class F>void IndexFault(F f,U64 address){bool found=false;try{f();}catch(const Monstey_GadbScalarFault&e){found=e.kind==Monstey_GadbScalarFaultKind::NativeDynamicIndexAssertion&&e.address==address;}Check(found);}
void Sizes(){++groups;for(U32 type=0;type<64;++type)for(U32 count:std::array<U32,5>{0,1,2,0x80000000,UINT32_MAX})for(U32 flags:std::array<U32,10>{0,1,0x7f,0x80,0x100,0x200,0x280,0x80000000,0xfffffd7f,UINT32_MAX}){++cases;Check(Monstey_GadbGeneratedFieldSize(type,count,flags)==LiteralSize(type,count,flags));}for(U32 type:std::array<U32,3>{0x10000,0x80000001,UINT32_MAX}){++cases;Check(Monstey_GadbGeneratedFieldSize(type,1,0)==0);Check(Monstey_GadbGeneratedFieldSize(type,0,0)==16);}}
void Prefix(){++groups;Image f;f.Setup();U32 rng=0x92345678;for(U32 n=1;n<=96;++n){f.Put(f.C()+8,n,4);std::vector<U32> hashes,offsets;U32 offset=0;for(U32 i=0;i<n;++i){rng=rng*1103515245u+12345;const U32 h=100+(rng%23),type=(rng>>8)%23,count=(rng>>16)%3,flags=(rng&0x400)?0x200u:0u;hashes.push_back(h);offsets.push_back(offset);f.Decl(i,h,type,count,flags);offset=(offset+LiteralSize(type,count,flags)+7)&~7u;}for(U32 query=95;query<=125;++query){++cases;const auto hit=std::find(hashes.begin(),hashes.end(),query);const auto index=static_cast<std::size_t>(hit-hashes.begin());Check(Monstey_GadbFindGeneratedField(f.M(),f.C(),query)==(hit==hashes.end()?0:f.T()+index*72));Check(Monstey_GadbGeneratedFieldOffset(f.M(),f.C(),query)==(hit==hashes.end()?UINT32_MAX:offsets[index]));}}}
void RawGates(){++groups;Image f(0x120000);f.Setup();const std::array<U32,7> indices{0,1,0x7fff,0x8000,0xfffe,0xffff,UINT32_MAX};for(U32 type=0;type<256;++type)for(U32 count:std::array<U32,5>{0,1,0x7fff,0x8000,0xffff})for(U32 index:indices){++cases;const auto word=static_cast<std::uint16_t>(type*257);f.Put(f.H()+10,type,1);f.Put(f.H()+12,count,2);f.Put(f.H()+14,word,2);const bool valid=(type%64==2)&&index<count;const U32 bits=0x80000001u^(type*0x10001u)^(count<<8)^index;const U32 fallback=bits^0x7fc12345u;f.Put(f.D(),fallback,4);if(valid)f.Put(f.V()+U64(word+index)*8,0xdecafbad00000000ull|bits,8);Check(Monstey_GadbReadScalarFloatBits(f.M(),f.R(),f.K(),index,valid?UINT64_MAX:f.D())==(valid?bits:fallback));if(valid)Check(f.Get(f.V()+U64(word+index)*8,8)==(0xdecafbad00000000ull|bits));}}
void Widths(){++groups;++cases;Image f;f.Setup();const auto tail=f.base+f.data.size()-4;f.Put(f.R()+16,tail,8);f.Put(tail,0x7f812345,4);Check(Monstey_GadbReadScalarFloatBits(f.M(),f.R(),f.K(),0,UINT64_MAX)==0x7f812345u);f.Put(f.R()+1,0x11,1);RangeFault([&]{(void)Monstey_GadbReadScalarFloatBits(f.M(),f.R(),f.K(),0,UINT64_MAX);},tail);RangeFault([&]{(void)Monstey_GadbReadGeneratedFloatBits(f.M(),f.R(),f.K(),0,UINT64_MAX);},tail);}
void Fixed(){++groups;Image f;f.Setup();for(U32 type:std::array<U32,8>{0,1,2,8,9,17,18,UINT32_MAX})for(U32 count:std::array<U32,5>{0,1,2,0x80000000,0xfffffffe})for(U32 flags:std::array<U32,2>{0,0x280})for(U32 index:std::array<U32,8>{0,1,2,3,7,0x80000000,0x80000001,UINT32_MAX}){++cases;const U32 effective=(type==8||type==9)?U32(index*2):index;const auto actual=f.V()+24;f.Decl(0,Image::hash,type,count,flags);f.Put(f.R()+16,actual-U64(effective)*8,8);const U64 bits=0x7ff1234500000000ull^U64(type)<<20^count^index;f.Put(actual,bits,8);const auto got=Monstey_GadbEvaluateGeneratedWord(f.M(),f.C(),f.K(),f.R(),index);Check(got.found&&got.value==bits);Check(Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),index,f.Out())==1);Check(f.Get(f.Out(),8)==bits);}}
void Dynamic(){++groups;Image f;f.Setup();for(U32 type:std::array<U32,4>{2,8,9,17})for(U32 index:std::array<U32,8>{0,1,2,0x7fffffff,0x80000000,0x80000001,0xfffffffe,UINT32_MAX}){const U32 effective=(type==8||type==9)?U32(index*2):index;for(U32 count:std::array<U32,5>{0,effective,U32(effective+1),0x80000001,UINT32_MAX}){++cases;f.Decl(0,Image::hash,type,UINT32_MAX);f.Put(f.R()+16,f.V(),8);f.Put(f.V()+8,count,4);const U64 bits=0xfedcba987f800001ull^index^U64(type)<<48;f.Put(f.A(),bits,8);f.Put(f.V(),f.A()-U64(effective)*8,8);f.Put(f.Out(),0xc0ffee,8);if(effective<count){auto got=Monstey_GadbEvaluateGeneratedWord(f.M(),f.C(),f.K(),f.R(),index);Check(got.found&&got.value==bits);Check(Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),index,f.Out())==1);Check(f.Get(f.Out(),8)==bits);}else{IndexFault([&]{(void)Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),index,UINT64_MAX);},f.V()+8);Check(f.Get(f.Out(),8)==0xc0ffee);}}}}
void CountFaultOrder(){++groups;++cases;Image f;f.Setup();const auto storage=f.base-8;f.Put(f.R()+16,storage,8);f.Decl(0,Image::hash,2,UINT32_MAX);f.Put(f.base,0,4);const auto before=f.data;IndexFault([&]{(void)Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),0,UINT64_MAX);},f.base);Check(f.data==before);f.Put(f.base,1,4);RangeFault([&]{(void)Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),0,UINT64_MAX);},storage);}
void Aliases(){++groups;for(bool dynamic:std::array<bool,2>{false,true})for(U32 type:std::array<U32,3>{2,8,9})for(U32 prefix=0;prefix<3;++prefix)for(U32 index=0;index<4;++index)for(U32 target=0;target<12;++target)for(int delta=-7;delta<=7;++delta){++cases;Image f;f.Setup();U32 offset=0;for(U32 j=0;j<prefix;++j){f.Decl(j,Image::hash+1+j,j?8u:1u,1);offset=(offset+(j?12u:5u)+7)&~7u;}f.Put(f.C()+8,prefix+1,4);f.Decl(prefix,Image::hash,type,dynamic?UINT32_MAX:1);const auto storage=f.V()+offset;const U32 effective=(type==8||type==9)?index*2:index;const auto source=dynamic?f.A()+U64(effective)*8:storage+U64(effective)*8;const U64 bits=0x800000017f812345ull^index^U64(target)<<32;if(dynamic){f.Put(storage,f.A(),8);f.Put(storage+8,9,4);}f.Put(source,bits,8);const std::array<U64,12> centers{f.K(),f.C(),f.C()+8,f.T()+72ull*prefix+32,f.T()+72ull*prefix+36,f.T()+72ull*prefix+40,f.R()+16,storage,storage+8,source,f.Out(),f.base+f.data.size()-16};const auto destination=static_cast<U64>(static_cast<std::int64_t>(centers[target])+delta);auto expected=f.data;for(std::size_t k=0;k<8;++k)expected[static_cast<std::size_t>(destination-f.base)+k]=static_cast<std::uint8_t>(bits>>(8*k));Check(Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),index,destination)==1);Check(f.data==expected);}}
void HashOnlyAndOffsetOrder(){++groups;++cases;Image f;f.Setup();const auto tail=f.base+f.data.size()-36;f.Put(f.C(),tail,8);f.Put(tail+32,Image::hash,4);Check(Monstey_GadbFindGeneratedField(f.M(),f.C(),Image::hash)==tail);Check(Monstey_GadbGeneratedFieldOffset(f.M(),f.C(),Image::hash)==0);Check(Monstey_GadbFindGeneratedField(f.M(),f.C(),Image::hash+1)==0);RangeFault([&]{(void)Monstey_GadbGeneratedFieldOffset(f.M(),f.C(),Image::hash+1);},tail+44);RangeFault([&]{(void)Monstey_GadbEvaluateGeneratedWord(f.M(),f.C(),f.K(),f.R(),0);},tail+36);}
void Defaults(){++groups;++cases;Image f;f.Setup();const U32 bits=0xffa12345;f.Put(f.D(),bits,4);Check(Monstey_GadbReadScalarFloatBits(f.M(),0,UINT64_MAX,UINT32_MAX,f.D())==bits);Check(Monstey_GadbReadGeneratedFloatBits(f.M(),0,UINT64_MAX,UINT32_MAX,f.D())==bits);f.Put(f.R()+24,0,8);Check(Monstey_GadbReadGeneratedFloatBits(f.M(),f.R(),UINT64_MAX,UINT32_MAX,f.D())==bits);f.Put(f.R()+24,f.O(),8);f.Put(f.O()+32,0,8);Check(Monstey_GadbReadGeneratedFloatBits(f.M(),f.R(),UINT64_MAX,UINT32_MAX,f.D())==bits);f.Put(f.O()+32,f.C(),8);f.Put(f.C()+8,0,4);Check(!Monstey_GadbEvaluateGeneratedWord(f.M(),f.C(),f.K(),UINT64_MAX,UINT32_MAX).found);Check(Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),UINT64_MAX,UINT32_MAX,UINT64_MAX)==0);Check(Monstey_GadbReadGeneratedFloatBits(f.M(),f.R(),f.K(),UINT32_MAX,f.D())==bits);RangeFault([&]{(void)Monstey_GadbEvaluateGeneratedWord(f.M(),UINT64_MAX,UINT64_MAX,0,0);},UINT64_MAX);}
void WrappedDeclarations(){++groups;++cases;Image f(0x10000,0);f.Setup();constexpr U64 row=UINT64_MAX-31;f.Put(f.C(),row,8);f.Put(0,Image::hash,4);f.Put(4,2,4);f.Put(8,1,4);f.Put(12,0,4);f.Put(f.V(),0xfedcba987f800001ull,8);Check(Monstey_GadbFindGeneratedField(f.M(),f.C(),Image::hash)==row);Check(Monstey_GadbGeneratedFieldOffset(f.M(),f.C(),Image::hash)==0);const auto got=Monstey_GadbEvaluateGeneratedWord(f.M(),f.C(),f.K(),f.R(),0);Check(got.found&&got.value==0xfedcba987f800001ull);f.Put(0,0,4);Check(Monstey_GadbFindGeneratedField(f.M(),UINT64_MAX-7,123)==0);Check(Monstey_GadbGeneratedFieldOffset(f.M(),UINT64_MAX-7,123)==UINT32_MAX);}
void IndirectComposition(){++groups;for(bool generated:std::array<bool,2>{false,true})for(U32 remap:std::array<U32,4>{0,1,7,255}){++cases;Image f;f.Setup();f.Put(f.R(),3,1);f.Put(f.R()+1,generated?0x10u:0u,1);f.Put(f.K(),0x5100,4);f.Decl(0,0x5100,2,1);for(U32 i=0;i<3;++i){f.Put(f.H()+U64(i)*16+4,0x5000+i*0x100,4);f.Put(f.H()+U64(i)*16+9,i==1?remap:0u,1);}const auto descriptor=f.H()+U64(remap)*16;f.Put(descriptor+10,0xc2,1);f.Put(descriptor+12,1,2);f.Put(descriptor+14,31,2);f.Put(f.V(),0xdecafbadff812345ull,8);f.Put(f.V()+31*8,0xdecafbad7f812346ull,8);Check(Monstey_GadbReadScalarFloatBits(f.M(),f.R(),f.K(),0,UINT64_MAX)==(generated?0xff812345u:0x7f812346u));}++cases;Image f(0x1000);f.Setup();f.Put(f.R(),3,1);f.Put(f.R()+1,0,1);f.Put(f.K(),0x5100,4);for(U32 i=0;i<3;++i){f.Put(f.H()+U64(i)*16+4,0x5000+i*0x100,4);f.Put(f.H()+U64(i)*16+9,i==1?255u:0u,1);}RangeFault([&]{(void)Monstey_GadbReadScalarFloatBits(f.M(),f.R(),f.K(),0,UINT64_MAX);},f.H()+255*16+10);}
void OutputFailuresAndNewCall(){++groups;for(std::size_t left=1;left<8;++left){++cases;Image f;f.Setup();f.Put(f.V(),0xfedcba987f800001ull,8);const auto before=f.data;const auto out=f.base+f.data.size()-left;RangeFault([&]{(void)Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),0,out);},out);Check(f.data==before);}++cases;Image f;f.Setup();const U64 value=0x7fc00123fefdfcfaull;f.Put(f.V(),value,8);Check(Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),0,f.K())==1);const auto before=f.data;Check(Monstey_GadbFetchGeneratedWord(f.M(),f.C(),f.K(),f.R(),0,UINT64_MAX)==0);Check(f.data==before);}
}
int main(){try{Sizes();Prefix();RawGates();Widths();Fixed();Dynamic();CountFaultOrder();Aliases();HashOnlyAndOffsetOrder();Defaults();WrappedDeclarations();IndirectComposition();OutputFailuresAndNewCall();std::cout<<"PASS independent_scalar groups="<<groups<<" cases="<<cases<<" checks="<<checks<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<" groups="<<groups<<" cases="<<cases<<" checks="<<checks<<'\n';return 1;}}